105	func (h *Handler) Download(c echo.Context) error {
106		namespace := c.Param("namespace")
107		name := c.Param("name")
108		provider := c.Param("provider")
109		version := c.Param("version")
110	
111		ctx := c.Request().Context()
112	
113		exists, err := h.store.HeadModule(ctx, namespace, name, provider, version)
114		if err != nil {
115			c.Logger().Errorf("failed to check module existence: %v", err)
116			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
117		}
118	
119		if !exists {
120			return c.JSON(http.StatusNotFound, map[string]string{"error": "module version not found"})
121		}
122	
123		url, err := h.store.PresignGetModule(ctx, namespace, name, provider, version, h.presignExpiry)
124		if err != nil {
125			c.Logger().Errorf("failed to generate presigned URL: %v", err)
126			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
127		}
128	
129		c.Response().Header().Set("X-Terraform-Get", url)
130		return c.NoContent(http.StatusNoContent)
131	}
