133	// Upload stores a module archive in S3. The existence check and write are not
134	// atomic (TOCTOU): a concurrent upload between HeadModule and PutModule could
135	// result in a silent overwrite because S3 PutObject is last-write-wins.
136	// Conditional writes (If-None-Match) are not universally supported across
137	// S3-compatible backends, so we accept this trade-off.
138	func (h *Handler) Upload(c echo.Context) error {
139		namespace := c.Param("namespace")
140		name := c.Param("name")
141		provider := c.Param("provider")
142		version := c.Param("version")
143	
144		ctx := c.Request().Context()
145	
146		exists, err := h.store.HeadModule(ctx, namespace, name, provider, version)
147		if err != nil {
148			c.Logger().Errorf("failed to check module existence: %v", err)
149			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
150		}
151		if exists {
152			return c.JSON(http.StatusConflict, map[string]string{"error": "module version already exists"})
153		}
154	
155		body := http.MaxBytesReader(c.Response(), c.Request().Body, h.maxUploadSize)
156		defer body.Close()
157	
158		header := make([]byte, len(gzipMagic))
159		if _, err := io.ReadFull(body, header); err != nil {
160			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is too small or empty"})
161		}
162		if header[0] != gzipMagic[0] || header[1] != gzipMagic[1] {
163			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is not a valid gzip archive"})
164		}
165	
166		// Buffer the full body so S3 PutObject gets a seekable reader, which the
167		// AWS SDK requires for checksum computation over non-TLS connections.
168		// This is bounded by MaxBytesReader so memory usage is capped at maxUploadSize.
169		rest, err := io.ReadAll(body)
170		if err != nil {
171			var maxBytesErr *http.MaxBytesError
172			if errors.As(err, &maxBytesErr) {
173				return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body exceeds maximum upload size"})
174			}
