func TestListVersions(t *testing.T) {
	tests := []struct {
		name           string
		namespace      string
		modName        string
		provider       string
		versions       []string
		storeErr       error
		expectedStatus int
		expectedBody   string
	}{
		{
			name:           "returns versions",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			versions:       []string{"1.0.0", "1.0.1"},
			expectedStatus: http.StatusOK,
			expectedBody:   `{"modules":[{"versions":[{"version":"1.0.0"},{"version":"1.0.1"}]}]}`,
		},
		{
			name:           "returns 404 when no versions found",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			versions:       []string{},
			expectedStatus: http.StatusNotFound,
		},
		{
			name:           "returns 500 on store error",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			storeErr:       assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, mockStore := setupTest(t)

			mockStore.On("ListVersions", mock.Anything, tt.namespace, tt.modName, tt.provider).
				Return(tt.versions, tt.storeErr)

			path := "/v1/modules/" + tt.namespace + "/" + tt.modName + "/" + tt.provider + "/versions"
			req := httptest.NewRequest(http.MethodGet, path, nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			assert.Equal(t, tt.expectedStatus, rec.Code)
			if tt.expectedBody != "" {
				assert.JSONEq(t, tt.expectedBody, rec.Body.String())
			}
		})
	}
}

func TestDownload(t *testing.T) {
	tests := []struct {
		name           string
		namespace      string
		modName        string
		provider       string
		version        string
		exists         bool
		headErr        error
		presignURL     string
		presignErr     error
		expectedStatus int
		expectedHeader string
	}{
		{
			name:           "returns presigned URL",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			exists:         true,
			presignURL:     "https://s3.amazonaws.com/bucket/hashicorp/consul/aws/1.0.0.tar.gz?signed",
			expectedStatus: http.StatusNoContent,
			expectedHeader: "https://s3.amazonaws.com/bucket/hashicorp/consul/aws/1.0.0.tar.gz?signed",
		},
		{
			name:           "returns 404 when module does not exist",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "9.9.9",
			exists:         false,
			expectedStatus: http.StatusNotFound,
		},
		{
			name:           "returns 500 on head error",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			headErr:        assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
		{
			name:           "returns 500 on presign error",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			exists:         true,
			presignErr:     assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, mockStore := setupTest(t)

			mockStore.On("HeadModule", mock.Anything, tt.namespace, tt.modName, tt.provider, tt.version).
				Return(tt.exists, tt.headErr)

			if tt.exists && tt.headErr == nil {
				mockStore.On("PresignGetModule", mock.Anything, tt.namespace, tt.modName, tt.provider, tt.version, mock.Anything).
					Return(tt.presignURL, tt.presignErr)
			}

			path := "/v1/modules/" + tt.namespace + "/" + tt.modName + "/" + tt.provider + "/" + tt.version + "/download"
			req := httptest.NewRequest(http.MethodGet, path, nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			assert.Equal(t, tt.expectedStatus, rec.Code)
			if tt.expectedHeader != "" {
				assert.Equal(t, tt.expectedHeader, rec.Header().Get("X-Terraform-Get"))
			}
		})
	}
}

func validGzipBody(t *testing.T) *bytes.Buffer {
	t.Helper()
	var buf bytes.Buffer
	gw := gzip.NewWriter(&buf)
	_, err := gw.Write([]byte("hello"))
	assert.NoError(t, err)
	assert.NoError(t, gw.Close())
	return &buf
}

func TestUpload(t *testing.T) {
	tests := []struct {
		name           string
		namespace      string
		modName        string
		provider       string
		version        string
		body           func(t *testing.T) *bytes.Buffer
		exists         bool
		headErr        error
		putErr         error
		expectedStatus int
	}{
		{
			name:           "upload succeeds",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			body:           validGzipBody,
			exists:         false,
			expectedStatus: http.StatusCreated,
		},
		{
			name:           "rejects duplicate version",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			body:           validGzipBody,
			exists:         true,
			expectedStatus: http.StatusConflict,
		},
		{
			name:      "rejects invalid gzip",
			namespace: "hashicorp",
			modName:   "consul",
			provider:  "aws",
			version:   "1.0.0",
			body: func(t *testing.T) *bytes.Buffer {
				t.Helper()
				return bytes.NewBufferString("not a gzip file")
			},
			exists:         false,
			expectedStatus: http.StatusBadRequest,
		},
		{
			name:      "rejects empty body",
			namespace: "hashicorp",
			modName:   "consul",
			provider:  "aws",
			version:   "1.0.0",
			body: func(t *testing.T) *bytes.Buffer {
				t.Helper()
				return bytes.NewBufferString("")
			},
			exists:         false,
			expectedStatus: http.StatusBadRequest,
		},
		{
			name:           "returns 500 on head error",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			body:           validGzipBody,
			headErr:        assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
		{
			name:           "returns 500 on put error",
			namespace:      "hashicorp",
			modName:        "consul",
			provider:       "aws",
			version:        "1.0.0",
			body:           validGzipBody,
			exists:         false,
			putErr:         assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, mockStore := setupTest(t)

			mockStore.On("HeadModule", mock.Anything, tt.namespace, tt.modName, tt.provider, tt.version).
				Return(tt.exists, tt.headErr).Maybe()

			if !tt.exists && tt.headErr == nil {
				mockStore.On("PutModule", mock.Anything, tt.namespace, tt.modName, tt.provider, tt.version, mock.Anything).
					Return(tt.putErr).Maybe()
			}

			body := tt.body(t)
			path := "/v1/modules/" + tt.namespace + "/" + tt.modName + "/" + tt.provider + "/" + tt.version
			req := httptest.NewRequest(http.MethodPut, path, body)
			req.Header.Set("Content-Type", "application/octet-stream")
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			assert.Equal(t, tt.expectedStatus, rec.Code)
		})
	}
}

