	e.ServeHTTP(rec, req)

	assert.Equal(t, http.StatusOK, rec.Code)
}

func TestReadyz(t *testing.T) {
	tests := []struct {
		name           string
		headBucketErr  error
		checkRWErr     error
		expectedStatus int
		expectedBody   string
	}{
		{
			name:           "returns 200 when all checks pass",
			expectedStatus: http.StatusOK,
		},
		{
			name:           "returns 503 when HeadBucket fails",
			headBucketErr:  assert.AnError,
			expectedStatus: http.StatusServiceUnavailable,
			expectedBody:   `{"error":"head bucket check failed"}`,
		},
		{
			name:           "returns 503 when CheckReadWrite fails",
			checkRWErr:     assert.AnError,
			expectedStatus: http.StatusServiceUnavailable,
			expectedBody:   `{"error":"read/write check failed"}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, mockStore := setupTest(t)

			mockStore.On("HeadBucket", mock.Anything).
				Return(tt.headBucketErr)

			if tt.headBucketErr == nil {
				mockStore.On("CheckReadWrite", mock.Anything).
					Return(tt.checkRWErr)
			}

			req := httptest.NewRequest(http.MethodGet, "/readyz", nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			assert.Equal(t, tt.expectedStatus, rec.Code)
			if tt.expectedBody != "" {
				assert.JSONEq(t, tt.expectedBody, rec.Body.String())
			}
		})
	}
}

func TestReadyzCachesCheckReadWrite(t *testing.T) {
	e := echo.New()
	mockStore := new(storage.MockClient)
	h := &Handler{store: mockStore, presignExpiry: 15 * time.Minute, maxUploadSize: testMaxUploadSize}
	h.Register(e)

	mockStore.On("HeadBucket", mock.Anything).Return(nil)
	mockStore.On("CheckReadWrite", mock.Anything).Return(nil)

	// First request — CheckReadWrite is called
	req := httptest.NewRequest(http.MethodGet, "/readyz", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, http.StatusOK, rec.Code)

	// Second request — CheckReadWrite should NOT be called again
	req = httptest.NewRequest(http.MethodGet, "/readyz", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, http.StatusOK, rec.Code)

	mockStore.AssertNumberOfCalls(t, "CheckReadWrite", 1)
	mockStore.AssertNumberOfCalls(t, "HeadBucket", 2)
}

func TestReadyzRetriesCheckReadWriteOnFailure(t *testing.T) {
	e := echo.New()
	mockStore := new(storage.MockClient)
	h := &Handler{store: mockStore, presignExpiry: 15 * time.Minute, maxUploadSize: testMaxUploadSize}
	h.Register(e)

	mockStore.On("HeadBucket", mock.Anything).Return(nil)
	mockStore.On("CheckReadWrite", mock.Anything).Return(assert.AnError).Once()
	mockStore.On("CheckReadWrite", mock.Anything).Return(nil).Once()

	// First request — CheckReadWrite fails, returns 503
	req := httptest.NewRequest(http.MethodGet, "/readyz", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, http.StatusServiceUnavailable, rec.Code)

	// Second request — CheckReadWrite retries and succeeds
	req = httptest.NewRequest(http.MethodGet, "/readyz", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, http.StatusOK, rec.Code)

	// Third request — cached, CheckReadWrite not called again
	req = httptest.NewRequest(http.MethodGet, "/readyz", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, http.StatusOK, rec.Code)

	mockStore.AssertNumberOfCalls(t, "CheckReadWrite", 2)
	mockStore.AssertNumberOfCalls(t, "HeadBucket", 3)
}

func TestUploadMaxSize(t *testing.T) {
	e := echo.New()
	mockStore := new(storage.MockClient)
	h := &Handler{store: mockStore, presignExpiry: 15 * time.Minute, maxUploadSize: 10}
	h.Register(e)

	mockStore.On("HeadModule", mock.Anything, "foo", "bar", "aws", "1.0.0").
		Return(false, nil)

	// Create a valid gzip that exceeds 10 bytes
	var buf bytes.Buffer
	gw := gzip.NewWriter(&buf)
	_, err := gw.Write([]byte(strings.Repeat("x", 100)))
	assert.NoError(t, err)
	assert.NoError(t, gw.Close())

	// Body is buffered before PutModule, so MaxBytesReader triggers during
	// ReadAll — PutModule should not be called at all.
	req := httptest.NewRequest(http.MethodPut, "/v1/modules/foo/bar/aws/1.0.0", &buf)
	req.Header.Set("Content-Type", "application/octet-stream")
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)

	assert.Equal(t, http.StatusBadRequest, rec.Code)
	mockStore.AssertNotCalled(t, "PutModule", mock.Anything, mock.Anything, mock.Anything, mock.Anything, mock.Anything, mock.Anything)
}

