func TestObjectKey(t *testing.T) {
	key := objectKey("hashicorp", "consul", "aws", "1.0.0")
	assert.Equal(t, "hashicorp/consul/aws/1.0.0.tar.gz", key)
}

func TestPrefix(t *testing.T) {
