		t.Run(tt.key, func(t *testing.T) {
			v, ok := extractVersion(tt.key, tt.prefix)
			assert.Equal(t, tt.valid, ok)
			if ok {
				assert.Equal(t, tt.expected, v)
			}
		})
	}
