package registry

import (
	"bytes"
	"compress/gzip"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/immuta/operations/services/crow/internal/storage"
	"github.com/labstack/echo/v4"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
)

const testMaxUploadSize = 10 * 1024 * 1024 // 10MB

func setupTest(t *testing.T) (*echo.Echo, *storage.MockClient) {
	t.Helper()
	e := echo.New()
	mockStore := new(storage.MockClient)
	h := &Handler{store: mockStore, presignExpiry: 15 * time.Minute, maxUploadSize: testMaxUploadSize}
	h.Register(e)
	return e, mockStore
}

func TestHealth(t *testing.T) {
	e, _ := setupTest(t)

	req := httptest.NewRequest(http.MethodGet, "/health", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)

	assert.Equal(t, http.StatusOK, rec.Code)
}

func TestServiceDiscovery(t *testing.T) {
	e, _ := setupTest(t)

	req := httptest.NewRequest(http.MethodGet, "/.well-known/terraform.json", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)

	assert.Equal(t, http.StatusOK, rec.Code)
	assert.JSONEq(t, `{"modules.v1": "/v1/modules/"}`, rec.Body.String())
}

func TestListVersions(t *testing.T) {
	tests := []struct {
		name           string
		modulePath     []string
		versions       []string
		storeErr       error
		expectedStatus int
		expectedBody   string
	}{
		{
			name:           "returns versions for standard 3-segment path",
			modulePath:     []string{"hashicorp", "consul", "aws"},
			versions:       []string{"1.0.0", "1.0.1"},
			expectedStatus: http.StatusOK,
			expectedBody:   `{"modules":[{"versions":[{"version":"1.0.0"},{"version":"1.0.1"}]}]}`,
		},
		{
			name:           "returns versions for deep nested path",
			modulePath:     []string{"myorg", "team", "infra", "consul", "aws"},
			versions:       []string{"2.0.0"},
			expectedStatus: http.StatusOK,
			expectedBody:   `{"modules":[{"versions":[{"version":"2.0.0"}]}]}`,
		},
		{
			name:           "returns versions for single-segment path",
			modulePath:     []string{"mymodule"},
			versions:       []string{"1.0.0"},
			expectedStatus: http.StatusOK,
			expectedBody:   `{"modules":[{"versions":[{"version":"1.0.0"}]}]}`,
		},
		{
			name:           "returns 404 when no versions found",
			modulePath:     []string{"hashicorp", "consul", "aws"},
			versions:       []string{},
			expectedStatus: http.StatusNotFound,
		},
		{
			name:           "returns 500 on store error",
			modulePath:     []string{"hashicorp", "consul", "aws"},
			storeErr:       assert.AnError,
			expectedStatus: http.StatusInternalServerError,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, mockStore := setupTest(t)

			mockStore.On("ListVersions", mock.Anything, tt.modulePath).
				Return(tt.versions, tt.storeErr)

			path := "/v1/modules/" + strings.Join(tt.modulePath, "/") + "/versions"
			req := httptest.NewRequest(http.MethodGet, path, nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			assert.Equal(t, tt.expectedStatus, rec.Code)
			if tt.expectedBody != "" {
				assert.JSONEq(t, tt.expectedBody, rec.Body.String())
			}
		})
	}
}

func TestDownload(t *testing.T) {
	tests := []struct {
		name           string
		modulePath     []string
		version        string
		exists         bool
		headErr        error
		presignURL     string
		presignErr     error
		expectedStatus int
		expectedHeader string
	}{
		{
			name:           "returns presigned URL for standard 3-segment path",
			modulePath:     []string{"hashicorp", "consul", "aws"},
			version:        "1.0.0",
			exists:         true,
			presignURL:     "https://s3.amazonaws.com/bucket/hashicorp/consul/aws/1.0.0.tar.gz?signed",
			expectedStatus: http.StatusNoContent,
			expectedHeader: "https://s3.amazonaws.com/bucket/hashicorp/consul/aws/1.0.0.tar.gz?signed",
		},
		{
			name:           "returns presigned URL for deep nested path",
			modulePath:     []string{"myorg", "team", "infra", "consul", "aws"},
			version:        "2.0.0",
			exists:         true,
			presignURL:     "https://s3.amazonaws.com/bucket/myorg/team/infra/consul/aws/2.0.0.tar.gz?signed",
			expectedStatus: http.StatusNoContent,
			expectedHeader: "https://s3.amazonaws.com/bucket/myorg/team/infra/consul/aws/2.0.0.tar.gz?signed",
		},
