	tests := []struct {
		modulePath []string
		expected   string
	}{
		{[]string{"hashicorp", "consul", "aws"}, "hashicorp/consul/aws/"},
		{[]string{"myorg", "team", "infra", "consul", "aws"}, "myorg/team/infra/consul/aws/"},
		{[]string{"single"}, "single/"},
	}
