package storage

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/s3"
	"github.com/aws/aws-sdk-go-v2/service/s3/types"
)

type S3Client struct {
	client     *s3.Client
	presigner  *s3.PresignClient
	bucketName string
}

func NewS3Client(awsCfg aws.Config, bucketName string, optFns ...func(*s3.Options)) *S3Client {
	client := s3.NewFromConfig(awsCfg, optFns...)
	return &S3Client{
		client:     client,
		presigner:  s3.NewPresignClient(client),
		bucketName: bucketName,
	}
}

// NewS3ClientWithPresignEndpoint creates an S3Client that uses a separate
// endpoint for generating presigned URLs. This is needed when the S3 backend
// is reachable internally at one address (e.g. http://rustfs:9000) but
// clients need presigned URLs pointing to an external address (e.g.
// http://localhost:9000).
func NewS3ClientWithPresignEndpoint(awsCfg aws.Config, bucketName, presignEndpoint string, optFns ...func(*s3.Options)) *S3Client {
	client := s3.NewFromConfig(awsCfg, optFns...)
	presignClient := s3.NewFromConfig(awsCfg, append(optFns, func(o *s3.Options) {
		o.BaseEndpoint = &presignEndpoint
	})...)
	return &S3Client{
		client:     client,
		presigner:  s3.NewPresignClient(presignClient),
		bucketName: bucketName,
	}
}

func objectKey(modulePath []string, version string) string {
	return strings.Join(modulePath, "/") + "/" + version + ".tar.gz"
}

func prefix(modulePath []string) string {
	return strings.Join(modulePath, "/") + "/"
}

func extractVersion(key, pfx string) (string, bool) {
	if !strings.HasPrefix(key, pfx) {
		return "", false
	}
	rest := strings.TrimPrefix(key, pfx)
	if !strings.HasSuffix(rest, ".tar.gz") {
		return "", false
	}
	version := strings.TrimSuffix(rest, ".tar.gz")
	if version == "" {
		return "", false
	}
	return version, true
}

func (s *S3Client) ListVersions(ctx context.Context, modulePath []string) ([]string, error) {
	pfx := prefix(modulePath)
	input := &s3.ListObjectsV2Input{
		Bucket: &s.bucketName,
		Prefix: &pfx,
	}

	var versions []string
	paginator := s3.NewListObjectsV2Paginator(s.client, input)
	for paginator.HasMorePages() {
		output, err := paginator.NextPage(ctx)
		if err != nil {
			return nil, fmt.Errorf("listing objects: %w", err)
		}
		for _, obj := range output.Contents {
			if obj.Key == nil {
				return nil, errors.New("listing objects: object key is nil")
			}
			if v, ok := extractVersion(*obj.Key, pfx); ok {
				versions = append(versions, v)
			}
		}
	}

	return versions, nil
}

func (s *S3Client) HeadModule(ctx context.Context, modulePath []string, version string) (bool, error) {
	key := objectKey(modulePath, version)
	_, err := s.client.HeadObject(ctx, &s3.HeadObjectInput{
		Bucket: &s.bucketName,
		Key:    &key,
	})
	if err != nil {
		var notFound *types.NotFound
		var noSuchKey *types.NoSuchKey
		if errors.As(err, &notFound) || errors.As(err, &noSuchKey) {
			return false, nil
		}
		return false, fmt.Errorf("head object: %w", err)
	}
	return true, nil
}

func (s *S3Client) PutModule(ctx context.Context, modulePath []string, version string, body io.Reader) error {
	key := objectKey(modulePath, version)
	contentType := "application/gzip"
	_, err := s.client.PutObject(ctx, &s3.PutObjectInput{
		Bucket:      &s.bucketName,
		Key:         &key,
		Body:        body,
		ContentType: &contentType,
	})
	if err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	return nil
}

func (s *S3Client) PresignGetModule(ctx context.Context, modulePath []string, version string, expiry time.Duration) (string, error) {
	key := objectKey(modulePath, version)
	req, err := s.presigner.PresignGetObject(ctx, &s3.GetObjectInput{
		Bucket: &s.bucketName,
		Key:    &key,
	}, s3.WithPresignExpires(expiry))
	if err != nil {
		return "", fmt.Errorf("presigning URL: %w", err)
	}
	return req.URL, nil
}

const readyzKey = ".readyz"

func (s *S3Client) HeadBucket(ctx context.Context) error {
	_, err := s.client.HeadBucket(ctx, &s3.HeadBucketInput{
		Bucket: &s.bucketName,
	})
	if err != nil {
		return fmt.Errorf("head bucket: %w", err)
	}
	return nil
}

func (s *S3Client) CheckReadWrite(ctx context.Context) error {
	body := strings.NewReader(time.Now().UTC().Format(time.RFC3339))
	_, err := s.client.PutObject(ctx, &s3.PutObjectInput{
		Bucket: &s.bucketName,
		Key:    aws.String(readyzKey),
		Body:   body,
	})
	if err != nil {
		return fmt.Errorf("readyz put object: %w", err)
	}

	_, err = s.client.HeadObject(ctx, &s3.HeadObjectInput{
		Bucket: &s.bucketName,
		Key:    aws.String(readyzKey),
	})
	if err != nil {
		return fmt.Errorf("readyz head object: %w", err)
	}

	return nil
}

