// Download handles GET /v1/modules/{modulePath...}/{version}/download.
// The path must have at least two segments so that modulePath has at least
// one element and version is non-empty.
func (h *Handler) Download(c echo.Context) error {
	raw := strings.TrimSuffix(c.Param("*"), "/download")
	segments := parsePathSegments(raw)
	if len(segments) < 2 || !validateSegments(segments) {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
	}
	modulePath := segments[:len(segments)-1]
	version := segments[len(segments)-1]

	ctx := c.Request().Context()

	exists, err := h.store.HeadModule(ctx, modulePath, version)
	if err != nil {
		c.Logger().Errorf("failed to check module existence: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}

	if !exists {
		return c.JSON(http.StatusNotFound, map[string]string{"error": "module version not found"})
	}

