	"strings"
	"sync/atomic"
	"time"

	"github.com/immuta/operations/services/crow/internal/storage"
	"github.com/labstack/echo/v4"
)

// validSegment matches a single path segment: starts with alphanumeric,
// followed by alphanumeric, dots, underscores, or hyphens.
var validSegment = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]*$`)

// validateSegments returns false if any segment contains characters outside
// the allowed set, guarding against path traversal and injection.
func validateSegments(segments []string) bool {
	for _, s := range segments {
		if !validSegment.MatchString(s) {
			return false
		}
	}
	return true
}

// gzipMagic is the two-byte header for gzip files.
var gzipMagic = []byte{0x1f, 0x8b}

type Handler struct {
	store         storage.Client
	presignExpiry time.Duration
	maxUploadSize int64
	rwPassed      atomic.Bool
}

func NewHandler(store storage.Client, presignExpiry time.Duration, maxUploadSize int64) *Handler {
	return &Handler{store: store, presignExpiry: presignExpiry, maxUploadSize: maxUploadSize}
}

func (h *Handler) Register(e *echo.Echo) {
	e.GET("/.well-known/terraform.json", h.ServiceDiscovery)
	e.GET("/v1/modules/*", h.moduleGET)
	e.PUT("/v1/modules/*", h.Upload)
	e.GET("/health", h.Health)
	e.GET("/livez", h.Livez)
	e.GET("/readyz", h.Readyz)
}

// moduleGET dispatches GET requests under /v1/modules/ based on the path suffix.
func (h *Handler) moduleGET(c echo.Context) error {
	path := c.Param("*")
	if strings.HasSuffix(path, "/versions") {
		return h.ListVersions(c)
	}
	if strings.HasSuffix(path, "/download") {
		return h.Download(c)
	}
	return c.JSON(http.StatusNotFound, map[string]string{"error": "path must end in /versions or /download"})
}

// parsePathSegments splits a URL path string into non-empty segments.
func parsePathSegments(path string) []string {
	parts := strings.Split(path, "/")
	segments := make([]string, 0, len(parts))
	for _, p := range parts {
		if p != "" {
			segments = append(segments, p)
		}
	}
	return segments
}

func (*Handler) Health(c echo.Context) error {
	return c.NoContent(http.StatusOK)
}

func (*Handler) Livez(c echo.Context) error {
	return c.NoContent(http.StatusOK)
}

func (h *Handler) Readyz(c echo.Context) error {
	ctx := c.Request().Context()

	if err := h.store.HeadBucket(ctx); err != nil {
		c.Logger().Errorf("readyz: %v", err)
		return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "head bucket check failed"})
	}

	if !h.rwPassed.Load() {
		if err := h.store.CheckReadWrite(ctx); err != nil {
			c.Logger().Errorf("readyz: %v", err)
			return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "read/write check failed"})
		}
		h.rwPassed.Store(true)
	}

	return c.NoContent(http.StatusOK)
}

func (*Handler) ServiceDiscovery(c echo.Context) error {
	return c.JSON(http.StatusOK, map[string]string{
		"modules.v1": "/v1/modules/",
	})
}

type versionEntry struct {
	Version string `json:"version"`
}

// ListVersions handles GET /v1/modules/{modulePath...}/versions.
// modulePath must have at least two segments (e.g. namespace/name/provider).
func (h *Handler) ListVersions(c echo.Context) error {
	raw := strings.TrimSuffix(c.Param("*"), "/versions")
	modulePath := parsePathSegments(raw)
	if len(modulePath) < 2 || !validateSegments(modulePath) {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
	}

	versions, err := h.store.ListVersions(c.Request().Context(), modulePath)
	if err != nil {
		c.Logger().Errorf("failed to list versions: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}

	if len(versions) == 0 {
		return c.JSON(http.StatusNotFound, map[string]string{"error": "module not found"})
	}

	entries := make([]versionEntry, len(versions))
	for i, v := range versions {
		entries[i] = versionEntry{Version: v}
	}

	resp := map[string]any{
		"modules": []map[string]any{
			{"versions": entries},
		},
	}

	return c.JSON(http.StatusOK, resp)
}

// Download handles GET /v1/modules/{modulePath...}/{version}/download.
// The path must have at least three segments so that modulePath has at least
// two elements and version is non-empty.
func (h *Handler) Download(c echo.Context) error {
	raw := strings.TrimSuffix(c.Param("*"), "/download")
	segments := parsePathSegments(raw)
	if len(segments) < 3 || !validateSegments(segments) {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
	}
	modulePath := segments[:len(segments)-1]
	version := segments[len(segments)-1]

	ctx := c.Request().Context()

	exists, err := h.store.HeadModule(ctx, modulePath, version)
	if err != nil {
		c.Logger().Errorf("failed to check module existence: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}

	if !exists {
		return c.JSON(http.StatusNotFound, map[string]string{"error": "module version not found"})
	}

	url, err := h.store.PresignGetModule(ctx, modulePath, version, h.presignExpiry)
	if err != nil {
		c.Logger().Errorf("failed to generate presigned URL: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}

	c.Response().Header().Set("X-Terraform-Get", url)
	return c.NoContent(http.StatusNoContent)
}

// Upload handles PUT /v1/modules/{modulePath...}/{version}.
// The path must have at least two segments so that modulePath has at least
// one element and version is non-empty.
//
// The existence check and write are not atomic (TOCTOU): a concurrent upload
// between HeadModule and PutModule could result in a silent overwrite because
// S3 PutObject is last-write-wins. Conditional writes (If-None-Match) are not
// universally supported across S3-compatible backends, so we accept this trade-off.
func (h *Handler) Upload(c echo.Context) error {
	segments := parsePathSegments(c.Param("*"))
	if len(segments) < 2 || !validateSegments(segments) {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid module path"})
	}
	modulePath := segments[:len(segments)-1]
	version := segments[len(segments)-1]

	ctx := c.Request().Context()

	exists, err := h.store.HeadModule(ctx, modulePath, version)
	if err != nil {
		c.Logger().Errorf("failed to check module existence: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}
	if exists {
		return c.JSON(http.StatusConflict, map[string]string{"error": "module version already exists"})
	}

	body := http.MaxBytesReader(c.Response(), c.Request().Body, h.maxUploadSize)
	defer body.Close()

	header := make([]byte, len(gzipMagic))
	if _, err := io.ReadFull(body, header); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is too small or empty"})
	}
	if header[0] != gzipMagic[0] || header[1] != gzipMagic[1] {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is not a valid gzip archive"})
	}

	// Buffer the full body so S3 PutObject gets a seekable reader, which the
	// AWS SDK requires for checksum computation over non-TLS connections.
	// This is bounded by MaxBytesReader so memory usage is capped at maxUploadSize.
	rest, err := io.ReadAll(body)
	if err != nil {
		var maxBytesErr *http.MaxBytesError
		if errors.As(err, &maxBytesErr) {
			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body exceeds maximum upload size"})
		}
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "failed to read request body"})
	}
	full := append(header, rest...)
	if err := h.store.PutModule(ctx, modulePath, version, bytes.NewReader(full)); err != nil {
		c.Logger().Errorf("failed to store module: %v", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
	}

	return c.NoContent(http.StatusCreated)
}

